//! The words of the in-app tutorial: sections of steps. Every claim here describes what Zest does today (checked against the code when it was written; Zest's own gaps are listed
//! honestly in the last section). A body is paragraphs separated by a blank line; a line starting with "- " is a bullet; `**bold**`; `[[open:key|label]]` opens a dialog and
//! `[[go:section|label]]` / `[[go:section:Step title|label]]` jumps inside the tutorial. `tests` checks every link and the house rules for written text.

pub struct Step { pub title: &'static str, pub body: &'static str }
pub struct Section { pub id: &'static str, pub title: &'static str, pub steps: &'static [Step] }

/// The dialogs a link may open: the menu keys `modal_ui` understands.
pub const OPEN_KEYS: &[&str] = &["add_game", "edit_home", "duplicates", "community", "plugins", "data", "playnite", "blacklist", "hltb", "settings", "update", "send_log", "emulators", "companion"];

pub const SECTIONS: &[Section] = &[
    Section { id: "getting-started", title: "Getting Started", steps: &[
        Step { title: "Welcome to Zest", body: "Zest is a game library manager that runs on your own computer. It keeps your Steam collection, and games from other stores and emulators, in one library you can browse, filter, track and pick from.\n\nThis tour covers what Zest does today. Jump to any section from the list, search for a word, or read it top to bottom. It is always under the menu button (the three lines, top left) > Tutorial." },
        Step { title: "The first start", body: "The first time Zest opens it shows a welcome window:\n\n- **Coming from PlayDate?** Zest finds a PlayDate library on this computer and offers to copy it: games, statuses, settings, sign-ins and covers. PlayDate keeps its own copy and still works. If Zest does not find it, choose PlayDate's folder yourself (the one with games_....db in it). See [[go:playdate|Moving from PlayDate]].\n- **Set up your library**: **SIGN IN WITH STEAM** (Steam's own login page; Zest fills in your SteamID and, when your account has one, your Web API key), **DETECT** to use the Steam account already on this computer, or type your Steam ID. Then **CREATE LIBRARY**.\n- **RESTORE A BACKUP...** starts from a Zest or PlayDate backup zip.\n\nAfterwards Zest shows **What's new** (what changed since PlayDate) when your library came from PlayDate, or this tutorial when you started fresh." },
        Step { title: "Three pages", body: "The bar at the top has three pages:\n\n- [[go:home|**Home**]]: shelves of games, a clock and charts.\n- [[go:library|**Library**]]: everything you own, with filters, sorting, grouping and bulk tools.\n- [[go:pick6|**Pick 6**]]: a \"what should I play next\" picker.\n\nEverything else (adding games, stores, backups, settings, updates) is behind the menu button at the top left. The button at the top right switches full screen, and **EXIT** closes Zest. Which page Zest opens on is set in [[open:settings|Settings]] > Appearance." },
        Step { title: "Adding your games", body: "Your Steam games are added when the library is made. After that, Zest checks your Steam library for new games every time it starts. Press **POPULATE ZEST** at the top of the menu whenever you want to check right away. It only adds what is missing, skips anything you removed on purpose, and fills in details, reviews, covers, ProtonDB ratings and HowLongToBeat times in the background. Covers for the games on screen come first.\n\nWithout a Steam Web API key Zest can only see the games Steam knows about on this computer, and it cannot read achievements. Add the key in [[open:settings|Settings]] > Accounts (Sign in with Steam fills it in for you) and press Populate again to get the whole library.\n\nTo add one game by hand, use [[open:add_game|**Add Game**]]: search Steam by name, paste an AppID or store link, or choose **MANUAL GAME** for a game with no store behind it. Games from other stores come from [[go:stores|Stores]], and ROMs from [[go:emulators|Emulators]]." },
        Step { title: "Launching a game", body: "Click a cover to play it. A Steam game opens through Steam (an uninstalled one gets Steam's install prompt). Games from other stores start through their store's launcher or from their own folder, and ROMs through their emulator.\n\nAfter you play a Steam game, its playtime and last-played date are read from Steam's own files the next time Zest starts." },
        Step { title: "The right-click menu", body: "Right-click a game, on any page, for quick actions: **Launch** or **Install**, **Open Store Page**, **Achievements** and **Community Hub** (Steam games), **Edit Game**, **Completion Status** (a submenu), **Uninstall** and **Delete**.\n\nDelete offers **DELETE AND BLACKLIST**, so a later Populate or sync does not bring the game back." },
        Step { title: "Mouse buttons", body: "What each mouse button does on a cover is up to you: [[open:settings|Settings]] > Library > **MOUSE**. Every button (left, middle, right and the two side buttons) can have a single-click and a double-click rule: launch, show the info tooltip, open the right-click menu, the store page, the install folder, the editor, Steam achievements, the Community Hub, or nothing.\n\nThe defaults: left click launches, right click opens the menu. Delete and uninstall are never mouse actions, so a stray click cannot remove anything. The same tab turns on the **card tooltip** (game details when you hover a cover) for each page and picks what it shows." },
        Step { title: "A controller", body: "A gamepad drives all of Zest: the D-pad or left stick moves (a cursor over covers, focus in dialogs), **A** confirms, **B** goes back, **X** opens a game's menu, **Y** edits it, **Start** launches the game under the cursor, **Back** opens the menu, and the bumpers page through the grid. Those are the defaults: any button can be changed in [[open:settings|Settings]] > Gamepad. Zest only listens while its window has the focus, so a game you are playing never moves it.\n\nSee [[go:gamepad|Gamepad]] for button mapping, shortcuts and controller setup." },
    ] },
    Section { id: "home", title: "Home", steps: &[
        Step { title: "Shelves and widgets", body: "Home shows your library as shelves, for example Recently Played, Installed or a random pick. Each shelf is a **filter** (which games it can show) plus a **sort**. Between them there can be widgets: a clock, and charts of your completion statuses and achievements.\n\nA shelf with more games than fit scrolls sideways. Hover a cover to see it grow; click it to launch." },
        Step { title: "Shuffle", body: "A shelf that is sorted randomly has a shuffle button. Press it to draw a fresh set without leaving the page." },
        Step { title: "Installed games follow your installs", body: "The Installed and Not Installed shelves update by themselves when a game is installed or uninstalled while Zest is open, whichever store it comes from." },
        Step { title: "Editing the page", body: "[[open:edit_home|**Edit Home Page**]] in the menu (also in Settings > Appearance) shows a scale model of the page. Drag a shelf to move it, drag a row's bottom edge or the bar between two shelves to resize them, and click a shelf to edit it below the map. Two or more shelves can share a row side by side (**ADD A SHELF TO THIS ROW...**, **UNSPLIT** to take one out). Nothing changes on Home until **SAVE**; **RESET SHELVES** goes back to the starting layout." },
        Step { title: "A shelf's settings", body: "For the selected shelf: its **Title**, the **Filter** (a built-in one or any saved filter), the **Platforms** it may show, how it is **Sorted** (high or low first, or shuffled), the number of **Covers**, and its **Height**. **Fill the rest** makes a row take whatever height the other rows leave. A shelf can be hidden instead of deleted; hidden shelves are listed at the bottom." },
        Step { title: "Shelf priority", body: "**SHELF PRIORITY...** sets which shelves keep a game to themselves: a shelf with **Skip games claimed by higher-priority shelves** never repeats a game that a shelf above it in the list already shows. Order the list to say which shelves win." },
        Step { title: "Widgets", body: "A row can hold a **WIDGET** instead of games: the **Clock** (12 or 24 hour time, seconds on or off, the date under it, and an optional title above), the **Completion chart** or the **Achievement chart**." },
    ] },
    Section { id: "library", title: "Library", steps: &[
        Step { title: "Layouts, sorting and grouping", body: "The **VIEW** button changes how the Library looks.\n\n- **Display**: a Vertical or Horizontal cover grid, or **List**, rows on the left and the selected game's details and editor on the right. The cover size is set here too.\n- **Sort by**: name, hours played, release date, recently played, date added, review score, weighted score, Metacritic score, HowLongToBeat times (main, extras, completionist, shortest, longest), achievement percentage, achievements remaining, total reviews, tag similarity (how close a game's tags are to games you finished) or random. A button flips ascending and descending.\n- **Group by**: installed, completion status, release date, date added, review score, weighted score or library, as headings in the grid.\n\nSorting and grouping apply at once, without reloading the list." },
        Step { title: "Search", body: "The search box at the top of the Library shows only games whose name contains what you type (capitals do not matter). Clear it to see everything again; **CLEAR** next to it removes the whole filter.\n\nWhen the Library shows no games at all, **Show All Games** clears the filter, the search and any hidden libraries at once." },
        Step { title: "Building a filter", body: "**FILTERS** opens the filter dialog.\n\n- **Simple** mode is a list of conditions joined by AND (all must match) or OR (any can match): title, tags, genres, categories, groups, status, library, installed, release date, date added, last played, playtime, review scores, Metacritic, achievements, developer, publisher, ProtonDB, HowLongToBeat times, art sources, cover quality and more. A condition can compare one field with another field instead of a value.\n- **Advanced** mode adds nested groups and a custom WHERE clause for anything the menus cannot say.\n- **Quick** status buttons and the **Libraries** list (Steam, GOG and so on) narrow it further.\n\n**APPLY** shows the result, **CLEAR ALL** starts over." },
        Step { title: "Cover Quality", body: "The **Cover Quality** condition finds covers that need work: low resolution, the wrong shape for the card, or missing, or the ones that are fine. Filter on it, then re-fetch them with Bulk Ops > Re-scrape > Artwork." },
        Step { title: "Saved filters", body: "**Saved filters...** in the dialog loads, saves, renames and deletes named filters. A saved filter can be a Home shelf's filter, narrow the pool Pick 6 draws from, color card outlines, and be used inside another filter with a Saved Filter condition (games in, or not in, another filter).\n\nTo share one, [[open:data|Data]] exports a saved filter as a small file and imports one; PlayDate reads and writes the same format." },
        Step { title: "Select games and Bulk Ops", body: "**BULK OPS** works on every game matching your filter, or on games you pick (choose **Pick games**: the Library goes into select mode, click covers, then open Bulk Ops again). Its tabs:\n\n- **Edit**: change one field on all of them. For lists such as tags and groups choose **Append** (add values), **Remove** (take values out) or **Replace** (overwrite). It says how many games change before you apply.\n- **Re-scrape**: Steam metadata, store data and reviews, artwork (with a choice of source, and an option to skip covers you set yourself), **Fill Missing Data**, ProtonDB and HowLongToBeat.\n- **Date Importer**: when you got each game, see [[go:metadata:Purchase dates|Purchase dates]].\n\n**BULK DELETE THESE GAMES** removes them and their covers for good." },
        Step { title: "Review scores", body: "A game can carry several scores. **Review %** is the share of positive Steam reviews. **Weighted %** pulls scores with few reviews toward 50 so a handful of reviews cannot make a game look great (how strongly is set in [[open:settings|Settings]] > Tuning). **Metacritic** is the critics' score where Steam lists one. All can be sorted, filtered and grouped on." },
        Step { title: "Outlines and badges", body: "Covers can carry a colored **outline** and small **badges** in their corners. In [[open:settings|Settings]] > Appearance, **CARD OUTLINES** colors a cover by rules (for example green for Completed, or any saved filter), and **CARD BADGES** chooses what each corner shows (the library a game is from, its status, review or HowLongToBeat bands, with your own icons if you like). Each can be on or off per page. The **edit button** (a pencil that appears on a hovered cover) has a corner of its own." },
    ] },
    Section { id: "pick6", title: "Pick 6", steps: &[
        Step { title: "What it does", body: "Pick 6 deals six games to choose from, so you do not have to scan the whole library. Press **PICK 6** to deal; press it again to deal a new six. Each pick can say why it was chosen." },
        Step { title: "Modes", body: "Choose how the six are chosen:\n\n- **RANDOM**: any game from the pool, with equal chances.\n- **SMART**: random, but only from games with a review score of at least 70%, leaning toward games whose tags match the games you finished. The 70% is **Smart mode review minimum** in [[open:settings|Settings]] > Tuning.\n- **WEIGHTED**: five sliders, each from a preference against to a preference for: **Tag Similarity**, **Review Score**, **Staleness** (how long since you played it), **Release Date** and **Length** (HowLongToBeat). Some take a minimum and maximum too; when too few games fit, Pick 6 says so.\n\nAll three are random draws, not a ranked top six, so you see different games each time. The formulas behind them are in [[open:settings|Settings]] > Tuning." },
        Step { title: "The pool", body: "**STATUS** chooses which completion statuses can be picked (Never Played, Unfinished and so on). **Use currently filtered games only** draws from whatever your Library filter shows." },
    ] },
    Section { id: "editing", title: "Editing a game", steps: &[
        Step { title: "Opening the editor", body: "Choose **Edit Game** in the right-click menu, press **Y** on a gamepad, or use the pencil on a hovered cover. In List mode the detail pane on the right is the editor." },
        Step { title: "What you can change", body: "Title, completion status, installed flag, last played, playtime, release date, date added, developers, publishers, genres, categories, tags, groups, description, free to play, and the review numbers. Tags and groups are comma separated.\n\nButtons: **OPEN FOLDER**, **CHANGE EXECUTABLE** (for games Zest starts from a folder: pick which file starts the game), **FILL MISSING DATA**, **SYNC** (re-read this game from its store), and **DELETE GAME**." },
        Step { title: "Which file starts a game", body: "For games Zest starts from a folder (Humble, itch.io, IndieGala, GOG), Zest picks the best file itself. When several files are equally good, it asks once which to use and remembers your answer for that game. **CHANGE EXECUTABLE** lets you choose again later." },
        Step { title: "Games on several stores", body: "When you own a game in more than one library, Zest shows one copy: the one from the library you rank highest. The editor shows a copy it thinks is the same game; **LINK** joins them by hand when the names differ, **UNLINK** separates them, and **NOT A DUPLICATE** says they are different games. See [[go:cleanup|Duplicates and the blacklist]]." },
    ] },
    Section { id: "art", title: "Cover art", steps: &[
        Step { title: "Where covers come from", body: "Zest fetches a vertical cover, a horizontal header and an icon for each game. By default it tries Steam, then the store's own art, then SteamGridDB, and takes the first picture that fits the card (if none fits, the first one found). A cover that does not fit the card is drawn with bars colored from its own edges.\n\n[[open:settings|Settings]] > Library > **ART** sets the order of the sources for each library and each kind of picture, and can switch a source off." },
        Step { title: "The art tabs", body: "In the editor, the **Vertical**, **Horizontal** and **Icon** tabs each show the current picture, where it came from, and these buttons:\n\n- **RE-SCRAPE**: fetch it again.\n- **FROM STEAM**: use the Steam version's art (for other stores' games).\n- **CUSTOM URL**: a web address or a file on your computer (**BROWSE...** picks one).\n- **SHOW FILE** and **CLEAR**.\n- **CROP**: move and zoom the picture inside the card's frame.\n- **BROWSE SGDB**: pick from SteamGridDB (needs a SteamGridDB key in [[open:settings|Settings]] > Accounts).\n\nA cover you chose, cropped or loaded from a file is marked Custom, so a bulk re-scrape can be told to leave it alone." },
        Step { title: "Many at once", body: "Bulk Ops > Re-scrape > **Artwork** re-fetches covers for many games, for any of the three kinds, from **Auto** (Steam, then SteamGridDB), **Steam only** (other stores' games use their Steam copy) or **SGDB only**. It can skip the covers you set yourself. The [[go:library:Cover Quality|Cover Quality]] filter finds the ones worth redoing." },
    ] },
    Section { id: "status", title: "Completion status", steps: &[
        Step { title: "The five statuses", body: "- **Never Played**\n- **Unfinished**\n- **Beaten**: your own call that you finished it.\n- **Completed**: 100 percent of achievements.\n- **Won't Play**: you decided not to, for any reason.\n\nChange one from the right-click menu, the editor, or in bulk." },
        Step { title: "What happens by itself", body: "At startup Zest reads Steam's own files: games with playtime move from Never Played to Unfinished. When a Steam game reaches 100 percent of its achievements it becomes Completed, and a Completed game that no longer shows 100 percent (the developer added achievements) goes back to Beaten. Each of the three can be switched off in [[open:settings|Settings]] > Library." },
    ] },
    Section { id: "metadata", title: "Details, dates and times", steps: &[
        Step { title: "Fill Missing Data", body: "**FILL MISSING DATA** (in the editor, and in Bulk Ops) completes what a game lacks. For a game from another store it finds the Steam page (through PCGamingWiki, then a Steam search), and uses it for tags, genres, reviews, the description and more. It never overwrites what is already there." },
        Step { title: "Purchase dates", body: "Bulk Ops > **Date Importer** > **Fetch Dates** sets Date Added to when you really got each game, replacing the date Zest first saw it.\n\n- Games from GOG, Epic Games, EA App, IndieGala and PlayStation ask the store's account in the background (the store must be connected).\n- Steam games read their activation date from Steam's Help pages, which Zest reads itself with your Steam sign-in (a Steam sign-in window opens first if you are not signed in). Once signed in, new Steam games also get their real date as they are added. Your Steam sign-in is kept safe the same way as store sign-ins, see [[go:stores:Where sign-ins are kept|Where sign-ins are kept]]." },
        Step { title: "HowLongToBeat", body: "[[open:hltb|**HLTB**]] in the menu lists every game's HowLongToBeat match. Matches below your threshold wait under **Needs review**: **CONFIRM** them, pick **OTHER MATCH** (search, or paste a HowLongToBeat address), or **NO PAGE** when the game has none. **CONFIRM ALL ABOVE** confirms every match scoring at least the slider's value, and **RE-SCRAPE UNMATCHED** tries again for games with no match." },
        Step { title: "ProtonDB", body: "Steam games get a ProtonDB rating (platinum to borked) from Bulk Ops > Re-scrape > ProtonDB. The tier and its confidence can be filtered on." },
        Step { title: "Tuning", body: "[[open:settings|Settings]] > **Tuning** adjusts the formulas behind tag similarity, weighted review scores and Pick 6, with a chart for each slider (solid is the slider, dashed is what is saved). Tag Similarity also lists your most liked and disliked tags, and you can pin a tag as liked, disliked or ignored." },
    ] },
    Section { id: "stores", title: "Stores", steps: &[
        Step { title: "The stores", body: "Open [[open:plugins|**Plugins**]] to connect a store. Each card has its own sign-in and **SYNC LIBRARY**. Built in: GOG, Epic Games, Humble Bundle, itch.io, IndieGala, Amazon Games, Xbox, PlayStation, Nintendo eShop, EA App, Ubisoft Connect, Battle.net, Rockstar Games and Legacy Games. Steam is always there." },
        Step { title: "Signing in", body: "Stores sign in in different ways, and the card explains its own:\n\n- **SIGN IN** opens the store's own login page in a sign-in window; Zest never sees your password.\n- **PlayStation** does not allow that window. Use **SIGN IN WITH BROWSER**, which needs the [[open:companion|Zest Companion userscript]] (install the Tampermonkey extension in your browser first), or follow the card's steps to paste the line Sony shows.\n- **Battle.net, Ubisoft Connect, Rockstar and Legacy Games** have no website sign-in Zest can use: sign in inside their own launcher, and Zest reads what the launcher saved. On Linux, give the Wine prefix the launcher is installed in, or let **INSTALL LAUNCHER** make one.\n\n**DISCONNECT** forgets a store's sign-in." },
        Step { title: "Where sign-ins are kept", body: "Store and Steam sign-ins are kept in your system's own secure storage: the keyring on Linux (GNOME Keyring or KWallet), the Keychain on a Mac, and Windows' per-user data protection. They are never written to your settings file in plain text.\n\nWhere there is no keyring (Steam Deck Game Mode, for example), Zest asks once what to do: keep sign-ins in a file only your user account can read, or forget them when Zest closes (you sign in again next time). [[open:settings|Settings]] > Account > **Sign-ins without a keyring** changes it later.\n\nAPI keys you type (Steam Web API, SteamGridDB) are always included in backups; store sign-ins only when you tick **Include store sign-ins**." },
        Step { title: "Install, launch and uninstall", body: "What Zest can do for a game depends on the store. It downloads and installs Humble, itch.io, IndieGala and GOG games itself, into the **Games folder** shown on the card, and runs a game's own setup program silently when it has one. Games from other stores start through their launcher. Zest removes files only inside its own games folder; on Windows, uninstalling a launcher's game runs that game's own uninstaller. Per-store details are in the card's notes." },
        Step { title: "Xbox and Game Pass", body: "The Xbox card reads the games you played on your account. With **Xodus Nexus** installed, **SYNC WITH NEXUS** also learns which games you own: choose **GROUP ONLY** (just mark them Owned, Game Pass or Played), **ADD MISSING**, or **ADD AND REMOVE** (Zest lists what it would delete and asks first)." },
        Step { title: "Sync at startup", body: "A card's **Sync this library when Zest starts** checkbox syncs that store shortly after the window opens, one store at a time, only when you are already signed in. New games appear while the sync runs." },
        Step { title: "Other plugins", body: "Third-party plugins are folders in the plugins folder (**OPEN PLUGIN FOLDER** shows where). They talk to Zest over a simple protocol, so they can be written in any language. PlayDate's old plugins are listed when one is found there; the stores they covered are built into Zest." },
    ] },
    Section { id: "community", title: "Community tools", steps: &[
        Step { title: "What they are", body: "[[open:community|**Community Tools**]] in the menu holds helpers for communities around SteamGifts. Zest is not part of any of them, and nothing is ever submitted for you." },
        Step { title: "PAGYWOSG and Monthly in a Month", body: "The two filter builders read the current (or upcoming) event's categories from the community's site and build a Library filter of the games that qualify, with a note on why each does. Categories that only you can count (**PERSONAL CATEGORIES**) are marked, and a saved event filter can be refreshed from live data later." },
        Step { title: "Secret Santa and Snowballs", body: "**Secret Santa / Snowballs** keeps your list of gift games from those events. They count as wins in the PAGYWOSG filter builder." },
        Step { title: "BLAEO, SteamGifts and Play or Pay", body: "- **Sync BLAEO** reads your BLAEO lists and shows what it would change before applying it.\n- **Sync SteamGifts Wins** reads your won giveaways in your own browser (through the [[open:companion|Zest Companion userscript]], because SteamGifts blocks programs) and puts those games in the \"Won on SteamGifts\" group. **Full refresh** re-checks every win and drops stale ones; **Wins not in your library...** lists the rest, with a way to add them.\n- **Sync Play or Pay Picks** tags your picks for the current cycle and keeps a \"Play or Pay\" filter up to date. When a new cycle starts it asks before removing the old cycle's groups." },
    ] },
    Section { id: "cleanup", title: "Duplicates and the blacklist", steps: &[
        Step { title: "Duplicates", body: "A game you own in several stores is shown once, as the copy from the library you rank highest; the others are hidden under it. [[open:settings|Settings]] > Library > **DUPLICATES** sets that ranking, or turns hiding off to see every copy.\n\n[[open:duplicates|**Duplicates**]] in the menu lists games that match only when an edition name is ignored (\"Game - Remastered\" and \"Game\"). Nothing is hidden until you approve it, and **Not duplicates** says no for good." },
        Step { title: "The blacklist", body: "Games you delete with **Delete and blacklist** go on the blacklist so a sync never adds them back. [[open:blacklist|**Blacklist / Junk Finder**]] lists them and lets you take one back." },
        Step { title: "Finding junk", body: "**Find Library Junk** (in the same dialog) suggests entries that are probably not real games: betas, demos, soundtracks or dev kits by their title, and, with an API key set, Steam games no longer on your account. **DEEP PLUGIN SCAN** asks each connected store about its games too. Review the lists, then blacklist, delete or whitelist the ones you pick; nothing changes until you press a button." },
    ] },
    Section { id: "data", title: "Backups and your data", steps: &[
        Step { title: "Backup and restore", body: "[[open:data|**Data**]] in the menu backs up your library, settings and (optionally) every cover into one zip, and restores one. Store sign-ins are left out unless you tick **Include store sign-ins** (they are then saved unencrypted in the zip); API keys are always included. Backups use PlayDate's layout, so each program can restore the other's. Restoring replaces your library: restart Zest afterwards." },
        Step { title: "Spreadsheets and other databases", body: "The Data dialog also:\n\n- exports your library as a CSV spreadsheet (all games, or what the Library shows), choosing the **COLUMNS**;\n- **imports from another database**: copies columns from another SQLite file (a PlayDate or Zest library, or your own) into this one, matched by AppID, after you map which column goes where." },
        Step { title: "Importing from Playnite", body: "[[open:playnite|**Import from Playnite**]] (in the Data dialog) reads a Playnite backup: dates added, last played and playtime (fill blanks only, or replace), completion statuses (you choose what each Playnite status becomes), and Playnite categories as groups. It can also add the Steam and GOG games Zest does not have yet. It shows what matched before writing anything, and **UNDO THE LAST IMPORT** puts everything back." },
        Step { title: "Your data folder", body: "Everything Zest keeps is in one folder: the library database, settings, covers and store data. It is next to Zest.exe on Windows, ~/Library/Application Support/Zest on a Mac, and ~/.local/share/zest on Linux (the Flatpak keeps its own under ~/.var/app). **OPEN DATA FOLDER** in the Data dialog opens it. Start Zest with a folder as its argument, or set ZEST_DATA, to use another." },
    ] },
    Section { id: "settings", title: "Settings and updates", steps: &[
        Step { title: "Settings", body: "[[open:settings|**Settings**]] is grouped:\n\n- **Account**: your Steam accounts (add, switch or remove one; a switch takes effect when Zest restarts), Sign in with Steam, the Web API key, your SteamGridDB key, your SteamGifts name, and what happens to sign-ins when no keyring is available (saved in a file, or forgotten when Zest closes).\n- **Appearance**: the background picture and opacity, themes and the theme editor, the page Zest starts on, UI scale, card outlines, card badges and the edit button, and Edit Home Layout.\n- **Library**: the completion sync switches and art preference, **ART** sources, **DUPLICATES** ranking, and **MOUSE** actions with the card tooltip.\n- **Gamepad**, **Tuning**, and **Advanced** (updates and support)." },
        Step { title: "Appearance", body: "[[open:settings|Settings]] > **Appearance** changes how Zest looks:\n\n- **Background & Opacity**: your own background picture, how strongly it shows through, or **CLEAR** for none.\n- **Theme**: pick a color theme. The **Theme Editor** changes any single color and saves the result as your own theme.\n- **UI SCALE** makes all text and controls bigger or smaller.\n- **Card outlines**, **card badges** and the **edit button** on covers, and which page Zest opens on.\n\nThe size of the covers themselves is set in the Library's **VIEW** button." },
        Step { title: "Updates", body: "[[open:update|**Check for Updates**]] looks for a newer Zest, shows what changed and installs it: the Flatpak reinstalls itself, a Windows install runs the new installer quietly and restarts, and other copies swap in the new program and restart. When a swapped-in version fails to start twice, the old one is put back and that version is not offered again. Zest also checks once a day when it starts (switch that off in the same dialog), and **Include beta versions** offers test releases. After an update, **What's new** lists the changes." },
        Step { title: "Getting help", body: "Settings > Advanced > [[open:send_log|**Send Log to Developer**]] sends Zest's log, with an optional message and a copy of your display settings, so a problem can be looked into. Keys, tokens and passwords are removed from the log first, and config.json (where your keys live) is never sent. **Discord** at the bottom of the menu opens the community server." },
    ] },
    Section { id: "gamepad", title: "Gamepad", steps: &[
        Step { title: "Moving around", body: "The D-pad or left stick moves a cursor over covers and the focus in dialogs; the right stick scrolls. By default **A** confirms, **B** goes back, **X** opens a game's menu, **Y** edits it, **Start** launches the game under the cursor, **Back** opens the menu, and the bumpers page through the grid. Every one of these can be moved to another button: see [[go:gamepad:Buttons and shortcuts|Buttons and shortcuts]]. **Gamepad input** in [[open:settings|Settings]] > Gamepad turns the controller off for Zest entirely." },
        Step { title: "Steam Deck", body: "- In Desktop Mode, add Zest to Steam as a non-Steam game (Steam > Games > Add a Non-Steam Game), then start it from Game Mode. There it runs full screen, and so do its sign-in windows (**B** or **CANCEL** closes one).\n- For a mouse pointer on the right trackpad, pick the **Gamepad with Mouse Trackpad** layout in Zest's controller settings in Steam. Steam's default layout for non-Steam games makes the trackpad act like a stick.\n- **Steam + X** opens the on-screen keyboard for typing.\n- Game Mode has no keyring, so Zest asks once where to keep sign-ins, see [[go:stores:Where sign-ins are kept|Where sign-ins are kept]].\n- After an update, **RESTART NOW** starts the new version through Steam, so it opens in Game Mode again." },
        Step { title: "Buttons and shortcuts", body: "Settings > Gamepad > **Gamepad Controls** sets what each button does: choose a row, then press the button you want. Taking a button another action has swaps the two. The **shortcuts** (Open Store Page, Open Install Folder, Open Achievements, Open Community Hub, each acting on the game under the cursor) start unset. **STICK FEEL** sets the dead zone and how fast a held button repeats." },
        Step { title: "Controller setup", body: "**Gamepad Setup** shows how Zest sees your controller:\n\n- **Controller test** draws the pad and lights each control as you press it (**TEST BUTTONS** stops the pad driving Zest meanwhile; hold B to finish).\n- **Button names**: a label style (Xbox, PlayStation, Nintendo or other) and your own names for single buttons.\n- Controllers SDL knows work as they are. For one it reads wrongly, **USE THIS LAYOUT** applies a known layout, or paste an SDL mapping line of your own." },
    ] },
    Section { id: "emulators", title: "Emulators", steps: &[
        Step { title: "Adding an emulator", body: "Menu > [[open:emulators|Emulators]] > **ADD AN EMULATOR**. Pick the one you use from the list (about fifty are known, for most Nintendo, Sony, Sega and arcade systems). Zest looks for its program on your search path, in Flatpak exports, in AppImage folders and in the usual install folders; **DETECT** tries again and **BROWSE** lets you pick it. An emulator that is not listed can be added at the bottom: a name, the system and its program." },
        Step { title: "ROM folders and scanning", body: "Give each system a ROM folder (a system can have several: **ADD FOLDER**), then **SCAN THIS SYSTEM** or **SCAN ALL**. Every file with a matching extension becomes a game, named from the file name without region codes and brackets, and its cover is fetched. A game that is already in the library, or on the blacklist, is skipped. PlayStation 3 folders and Vita3K installs are found in the emulator's own game folder, and Vita titles are named from the game's own data. MAME and FBNeo games are named by MAME when it is installed." },
        Step { title: "Playing, arguments and cores", body: "Launching a ROM game runs the emulator with the arguments shown for it: **{rom}** is the game file, **{rom_dir}** its folder, **{rom_name}** its name without the extension. RetroArch also needs a core for each system (**FIND** lists the ones installed, in the order that suits the system best). If a Flatpak emulator cannot see your ROM folder, the entry says so and shows the one command that fixes it. At start Zest checks that each ROM is still on disk and marks the game not installed when it is gone." },
    ] },
    Section { id: "linux", title: "Windows games on Linux and Mac", steps: &[
        Step { title: "Proton and Wine", body: "On Linux, Windows games from other stores run through Proton (with umu-run when it is installed) or else through Wine. Zest finds them by itself, in the usual Steam and distro folders. Each game, or each launcher, gets its own Wine prefix." },
        Step { title: "Launchers", body: "Some stores need their own launcher (Epic, EA App, Ubisoft Connect, Battle.net, Rockstar, Legacy Games). **INSTALL LAUNCHER** on the store's card downloads and runs its installer in a prefix of its own, then you sign in to it once. **START LAUNCHER** opens it, and **UNINSTALL LAUNCHER** removes it (with its games)." },
        Step { title: "In a Flatpak", body: "Inside a Flatpak, Zest runs Wine, Proton and the games on your computer itself, outside the sandbox, so the same Proton and Wine you already have are used." },
        Step { title: "On a Mac", body: "A launcher-based store runs through Wine on a Mac; Zest can download Wine into its own folder for it. It will likely not work: on the Mac tested so far, launchers either failed to install or never opened their window. Newer Macs may do better." },
    ] },
    Section { id: "playdate", title: "Moving from PlayDate", steps: &[
        Step { title: "A separate app", body: "Zest is the successor to PlayDate, rewritten from scratch. It installs next to PlayDate rather than over it, and on its first start it can copy your PlayDate library (see [[go:getting-started:The first start|The first start]]). PlayDate keeps its own copy and still works, so you can go back to it at any time. Once you are happy with Zest you can uninstall PlayDate.\n\nTaskbar pins, Steam shortcuts and menu entries that pointed at PlayDate need adding again for Zest." },
    ] },
];

#[cfg(test)]
mod tests {
    use super::*;
    /// `[[kind:target|label]]` links in a body.
    fn links(body: &str) -> Vec<(String, String)> {
        let mut out = vec![]; let mut rest = body;
        while let Some(i) = rest.find("[[") { let Some(j) = rest[i..].find("]]") else { break }; let inner = &rest[i + 2..i + j]; let (spec, _) = inner.split_once('|').unwrap_or((inner, "")); let (k, t) = spec.split_once(':').unwrap_or((spec, "")); out.push((k.to_string(), t.to_string())); rest = &rest[i + j + 2..]; }
        out
    }
    #[test] fn every_link_points_somewhere_and_every_section_and_step_is_there() {
        let ids: Vec<&str> = SECTIONS.iter().map(|s| s.id).collect();
        assert_eq!(ids.len(), { let mut v = ids.clone(); v.sort(); v.dedup(); v.len() }, "section ids are unique");
        for s in SECTIONS {
            assert!(!s.steps.is_empty() && !s.title.is_empty(), "{}", s.id);
            let titles: Vec<&str> = s.steps.iter().map(|x| x.title).collect();
            assert_eq!(titles.len(), { let mut v = titles.clone(); v.sort(); v.dedup(); v.len() }, "step titles in {} are unique", s.id);
            for st in s.steps {
                assert!(!st.body.trim().is_empty(), "{}: {}", s.id, st.title);
                for (k, t) in links(st.body) {
                    match k.as_str() {
                        "open" => assert!(OPEN_KEYS.contains(&t.as_str()), "{}: {} opens an unknown dialog {t}", s.id, st.title),
                        "go" => { let (sec, step) = t.split_once(':').map_or((t.as_str(), None), |(a, b)| (a, Some(b))); let target = SECTIONS.iter().find(|x| x.id == sec).unwrap_or_else(|| panic!("{}: {} goes to unknown section {sec}", s.id, st.title)); if let Some(step) = step { assert!(target.steps.iter().any(|x| x.title == step), "no step {step} in {sec}"); } }
                        o => panic!("unknown link kind {o}"),
                    }
                }
            }
        }
    }
    #[test] fn the_text_follows_the_house_rules() {
        for s in SECTIONS { for t in std::iter::once(s.title).chain(s.steps.iter().flat_map(|x| [x.title, x.body])) {
            assert!(!t.contains('\u{2014}') && !t.contains('\u{2013}'), "no em or en dashes: {t}");
            assert!(t.matches("**").count() % 2 == 0 && t.matches("[[").count() == t.matches("]]").count(), "balanced markup: {t}");
        } }
    }
}
